commands:
set -euo pipefail
export GIT_TERMINAL_PROMPT=0
WORK="$(mktemp -d /tmp/bloomml-telemetry-regression.XXXXXX)"
git clone --quiet --branch main https://github.com/MichalMatu/bloomml.git "$WORK/source"
cd "$WORK/source"
EXPECTED=0584ceb0182c15c0cf034385731aa957303d1924
test "$(git rev-parse HEAD)" = "$EXPECTED"
python3 - <<'PY'
from pathlib import Path
p=Path('test/test_stage27_telemetry/test_main.cpp')
s=p.read_text()
anchor='  char too_small[32]{};'
assert s.count(anchor)==1
new='''  // The storage worker reuses one scratch buffer for all three record types.
  // A shorter subsequent record must not expose bytes from the previous one.
  char scratch[1024];
  std::memset(scratch, 'X', sizeof(scratch));
  assert(formatStage27SessionNdjson(scratch, sizeof(session_buffer), session) == session_length);
  assert(std::strlen(scratch) == session_length);
  assert(std::strcmp(scratch, session_buffer) == 0);
  assert(formatStage27SampleNdjson(scratch, sizeof(scratch), snapshot) == sample_length);
  assert(std::strlen(scratch) == sample_length);
  assert(std::strcmp(scratch, sample_buffer) == 0);
  assert(formatStage27HealthNdjson(scratch, sizeof(scratch), snapshot, storage) == health_length);
  assert(std::strlen(scratch) == health_length);
  assert(std::strcmp(scratch, health_buffer) == 0);
  assert(formatStage27SessionNdjson(scratch, sizeof(session_buffer), session) == session_length);
  assert(std::strlen(scratch) == session_length);
  assert(std::strcmp(scratch, session_buffer) == 0);

'''
p.write_text(s.replace(anchor,new+anchor))
PY
git diff --check
cmake -S test/host -B "$WORK/build" -DCMAKE_BUILD_TYPE=Debug
cmake --build "$WORK/build" --target stage27_telemetry_tests stage27_file_durability_tests output_execution_telemetry_tests --parallel 1
ctest --test-dir "$WORK/build" -R '^(stage27_telemetry_tests|stage27_file_durability_tests|output_execution_telemetry_tests)$' --output-on-failure --no-tests=error
git diff --stat
test "$(git ls-remote --heads origin main | awk '{print $1}')" = "$EXPECTED"
git add test/test_stage27_telemetry/test_main.cpp
git commit -m "test: cover reused telemetry formatting scratch buffer"
git push origin HEAD:main
echo "PUSHED_SHA|$(git rev-parse HEAD)"
